const now = new Date();
const istOffset = 5.5 * 60 * 60 * 1000;
const istNow = new Date(now.getTime() + istOffset);
const yesterday = new Date(istNow);
yesterday.setDate(yesterday.getDate() - 1);
const year = yesterday.getFullYear();
const month = String(yesterday.getMonth() + 1).padStart(2, '0');
const day = String(yesterday.getDate()).padStart(2, '0');
return { reportType: 'daily', startDate: `${year}-${month}-${day}`, endDate: `${year}-${month}-${day}`, dateLabel: `${day}/${month}/${year}` };

const now = new Date();
const istOffset = 5.5 * 60 * 60 * 1000;
const istNow = new Date(now.getTime() + istOffset);
const lastMonday = new Date(istNow);
const dayOfWeek = lastMonday.getDay();
const daysToLastMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
lastMonday.setDate(lastMonday.getDate() - daysToLastMonday - 7);
const lastSunday = new Date(lastMonday);
lastSunday.setDate(lastMonday.getDate() + 6);
const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const lbl = (d) => `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}`;
return { reportType: 'weekly', startDate: fmt(lastMonday), endDate: fmt(lastSunday), dateLabel: `${lbl(lastMonday)} - ${lbl(lastSunday)} ${lastSunday.getFullYear()}` };

const now = new Date();
const istOffset = 5.5 * 60 * 60 * 1000;
const istNow = new Date(now.getTime() + istOffset);
const first = new Date(istNow.getFullYear(), istNow.getMonth() - 1, 1);
const last = new Date(istNow.getFullYear(), istNow.getMonth(), 0);
const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
return { reportType: 'monthly', startDate: fmt(first), endDate: fmt(last), dateLabel: `${months[first.getMonth()]} ${first.getFullYear()}` };

// Get date info from date calculation nodes
let dateInfo;
try { dateInfo = $('Daily Dates').first().json; } catch(e) {
  try { dateInfo = $('Weekly Dates').first().json; } catch(e2) {
    dateInfo = $('Monthly Dates').first().json;
  }
}

let employees = [];
let summaries = [];

try { employees = $('Fetch Employees').all().map(i => i.json); } catch(e) {}
try { summaries = $('Fetch Summary').all().map(i => i.json); } catch(e) {}

if (employees.length === 1 && Array.isArray(employees[0])) employees = employees[0];
if (summaries.length === 1 && Array.isArray(summaries[0])) summaries = summaries[0];

const uniqueSummaries = [...new Map(summaries.map(s => [s.id, s])).values()];

const empMap = new Map();
for (const e of employees) {
  empMap.set(e.id, { id: e.id, full_name: e.full_name || 'Unknown', email: e.email || '', department: e.department || 'Unassigned', total_seconds: 0, sessions: 0, days: 0, top_app: '', top_app_seconds: 0 });
}

for (const s of uniqueSummaries) {
  const emp = empMap.get(s.employee_id);
  if (emp) {
    emp.total_seconds += s.total_seconds || 0;
    emp.sessions += s.session_count || 0;
    emp.days += 1;
    if ((s.top_app_seconds || 0) > emp.top_app_seconds) {
      emp.top_app = s.top_app || 'None';
      emp.top_app_seconds = s.top_app_seconds || 0;
    }
  }
}

const fmt = (s) => { const h = Math.floor(s/3600); const m = Math.floor((s%3600)/60); return h > 0 ? `${h}h ${m}m` : `${m}m`; };

const list = [];
for (const [id, emp] of empMap) {
  if (emp.total_seconds === 0) continue;
  list.push({ ...emp, total_fmt: fmt(emp.total_seconds), avg_daily: emp.days > 0 ? fmt(Math.round(emp.total_seconds / emp.days)) : '0m' });
}

list.sort((a, b) => b.total_seconds - a.total_seconds);

const totalSeconds = list.reduce((s, e) => s + e.total_seconds, 0);

return { reportType: dateInfo.reportType || 'daily', dateLabel: dateInfo.dateLabel || '', startDate: dateInfo.startDate || '', endDate: dateInfo.endDate || '', summary: { employees: list.length, total_time: fmt(totalSeconds), total_sessions: list.reduce((s,e) => s + e.sessions, 0), avg: fmt(Math.round(totalSeconds / (list.length || 1))) }, employees: list };

const d = $input.first().json;
const gen = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });
const titles = { daily: '📊 Daily Report', weekly: '📈 Weekly Report', monthly: '📅 Monthly Report' };
const title = `${titles[d.reportType] || 'Report'} - ${d.dateLabel}`;

const maxTime = Math.max(...d.employees.map(e => e.total_seconds), 1);

let html = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);padding:20px}
.container{max-width:900px;margin:0 auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.3)}
.header{background:linear-gradient(135deg,#667eea,#764ba2);color:#fff;padding:40px;text-align:center;position:relative}
.header::after{content:'';position:absolute;bottom:0;left:0;right:0;height:4px;background:linear-gradient(90deg,#f093fb,#f5576c,#4facfe,#00f2fe)}
.header h1{font-size:32px;font-weight:700;margin-bottom:10px;text-shadow:0 2px 10px rgba(0,0,0,.2)}
.header .date{font-size:14px;opacity:.9}
.stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:20px;padding:30px;background:#f8f9ff}
.stat-card{background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);color:#fff;border-radius:16px;padding:25px;text-align:center;box-shadow:0 8px 16px rgba(102,126,234,.4);transition:transform .3s}
.stat-card:hover{transform:translateY(-5px)}
.stat-value{font-size:36px;font-weight:700;margin-bottom:8px}
.stat-label{font-size:13px;opacity:.9;text-transform:uppercase;letter-spacing:1px}
.section{padding:30px}
.section-title{font-size:22px;font-weight:700;color:#333;margin-bottom:25px;border-bottom:3px solid #667eea;padding-bottom:10px}
.emp-card{background:linear-gradient(135deg,#f8f9ff 0%,#fff 100%);border-radius:16px;padding:25px;margin-bottom:20px;border-left:5px solid #667eea;box-shadow:0 4px 12px rgba(0,0,0,.08);transition:all .3s}
.emp-card:hover{box-shadow:0 8px 24px rgba(0,0,0,.12);transform:translateX(5px)}
.emp-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}
.emp-info h3{font-size:20px;color:#333;margin-bottom:5px}
.emp-info p{font-size:13px;color:#888}
.emp-time{font-size:32px;font-weight:700;color:#667eea}
.progress-bar{background:#e8ecff;border-radius:10px;height:12px;margin:15px 0;overflow:hidden;position:relative}
.progress-fill{height:100%;background:linear-gradient(90deg,#667eea,#764ba2);border-radius:10px;transition:width 1s ease}
.stats-row{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:15px;margin-top:15px}
.mini-stat{background:#fff;padding:15px;border-radius:10px;text-align:center;box-shadow:0 2px 8px rgba(0,0,0,.05)}
.mini-stat-value{font-size:20px;font-weight:700;color:#667eea;margin-bottom:5px}
.mini-stat-label{font-size:11px;color:#999;text-transform:uppercase}
.top-app{background:#667eea;color:#fff;display:inline-block;padding:8px 16px;border-radius:20px;font-size:14px;font-weight:600;margin-top:10px}
.footer{background:#f5f5f5;padding:25px;text-align:center;font-size:13px;color:#888}
@media(max-width:600px){.stats-grid{grid-template-columns:1fr}.emp-header{flex-direction:column;gap:15px}}
</style></head><body>
<div class="container">
<div class="header"><h1>${title}</h1><div class="date">Generated: ${gen}</div></div>
<div class="stats-grid">
<div class="stat-card"><div class="stat-value">${d.summary.employees}</div><div class="stat-label">Employees</div></div>
<div class="stat-card"><div class="stat-value">${d.summary.total_time}</div><div class="stat-label">Total Time</div></div>
<div class="stat-card"><div class="stat-value">${d.summary.total_sessions}</div><div class="stat-label">Sessions</div></div>
<div class="stat-card"><div class="stat-value">${d.summary.avg}</div><div class="stat-label">Avg/Employee</div></div>
</div>
<div class="section"><h2 class="section-title">👥 Employee Performance</h2>`;

for (const e of d.employees) {
  const barWidth = (e.total_seconds / maxTime * 100).toFixed(1);
  html += `<div class="emp-card"><div class="emp-header"><div class="emp-info"><h3>${e.full_name}</h3><p>${e.department}${e.email ? ' • ' + e.email : ''}</p></div><div class="emp-time">${e.total_fmt}</div></div><div class="progress-bar"><div class="progress-fill" style="width:${barWidth}%"></div></div><div class="stats-row"><div class="mini-stat"><div class="mini-stat-value">${e.sessions}</div><div class="mini-stat-label">Sessions</div></div><div class="mini-stat"><div class="mini-stat-value">${e.days}</div><div class="mini-stat-label">Days Active</div></div><div class="mini-stat"><div class="mini-stat-value">${e.avg_daily}</div><div class="mini-stat-label">Avg Daily</div></div></div><div class="top-app">🏆 Top App: ${e.top_app}</div></div>`;
}

html += `</div><div class="footer"><p><strong>Screen Time Monitoring System</strong></p><p>Automated report for productivity tracking</p></div></div></body></html>`;

return { subject: title, html };
